import { useState, FormEvent } from 'react';

export function AccountSettings() {
  const [saved, setSaved] = useState(false);

  const handleSave = (e: FormEvent) => {
    e.preventDefault();
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  return (
    <div className="space-y-6">
      <Section title="Profile" description="Update your name and public information.">
        <form onSubmit={handleSave} className="space-y-4">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-violet-500 to-fuchsia-500 flex items-center justify-center text-white font-bold text-lg">AL</div>
            <button type="button" className="text-sm text-violet-600 hover:text-violet-700 font-medium">Change avatar</button>
          </div>
          <FormRow id="fullName" label="Full name" defaultValue="Alice Langdon" />
          <FormRow id="username" label="Username" defaultValue="alice" />
          <FormRow id="bio" label="Bio" defaultValue="Senior product designer" textarea />
          <SaveButton saved={saved} />
        </form>
      </Section>

      <Section title="Email address" description="Your email is used for login and notifications.">
        <form onSubmit={handleSave} className="space-y-4">
          <FormRow id="email" label="Email" defaultValue="alice@acme.com" type="email" />
          <SaveButton saved={saved} />
        </form>
      </Section>

      <Section title="Danger zone" description="Irreversible actions for your account.">
        <button type="button" className="px-4 py-2 rounded-lg border border-rose-300 text-rose-600 text-sm font-medium hover:bg-rose-50 transition-colors">
          Delete account
        </button>
      </Section>
    </div>
  );
}

function FormRow({ id, label, defaultValue, type = 'text', textarea = false }: { id: string; label: string; defaultValue?: string; type?: string; textarea?: boolean }) {
  return (
    <div>
      <label htmlFor={id} className="block text-xs font-medium text-slate-600 mb-1.5">{label}</label>
      {textarea ? (
        <textarea id={id} defaultValue={defaultValue} rows={2} className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:border-violet-400 focus:outline-none focus:ring-2 focus:ring-violet-100 resize-none transition-all" />
      ) : (
        <input id={id} type={type} defaultValue={defaultValue} className="w-full h-9 px-3 text-sm rounded-lg border border-slate-200 focus:border-violet-400 focus:outline-none focus:ring-2 focus:ring-violet-100 transition-all" />
      )}
    </div>
  );
}

function SaveButton({ saved }: { saved: boolean }) {
  return (
    <button type="submit" className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
      saved ? 'bg-emerald-500 text-white' : 'bg-violet-600 hover:bg-violet-500 text-white'
    }`}>
      {saved ? '✓ Saved' : 'Save changes'}
    </button>
  );
}

function Section({ title, description, children }: { title: string; description: string; children: React.ReactNode }) {
  return (
    <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
      <h2 className="font-semibold text-slate-800 mb-0.5">{title}</h2>
      <p className="text-sm text-slate-500 mb-5">{description}</p>
      {children}
    </div>
  );
}

