import { useState } from 'react';
import { Sun, Moon, Monitor } from 'lucide-react';

const THEMES = [
  { id: 'light',  label: 'Light',  icon: Sun,     preview: 'bg-white border-slate-200' },
  { id: 'dark',   label: 'Dark',   icon: Moon,    preview: 'bg-slate-900 border-slate-700' },
  { id: 'system', label: 'System', icon: Monitor, preview: 'bg-gradient-to-br from-white to-slate-900 border-slate-300' },
];

const ACCENTS = [
  { id: 'violet', cls: 'bg-violet-600' },
  { id: 'sky',    cls: 'bg-sky-500' },
  { id: 'rose',   cls: 'bg-rose-500' },
  { id: 'amber',  cls: 'bg-amber-500' },
  { id: 'emerald',cls: 'bg-emerald-500' },
];

export function AppearanceSettings() {
  const [theme, setTheme] = useState('light');
  const [accent, setAccent] = useState('violet');
  const [density, setDensity] = useState('comfortable');

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
        <h2 className="font-semibold text-slate-800 mb-0.5">Theme</h2>
        <p className="text-sm text-slate-500 mb-5">Choose how UIGen looks to you.</p>
        <div className="grid grid-cols-3 gap-3">
          {THEMES.map(t => (
            <button key={t.id} onClick={() => setTheme(t.id)}
              className={`flex flex-col items-center gap-2 p-4 rounded-xl border-2 transition-all ${
                theme === t.id ? 'border-violet-600 bg-violet-50' : 'border-slate-200 hover:border-slate-300'
              }`}
            >
              <div className={`w-full aspect-video rounded-lg border ${t.preview}`} />
              <div className="flex items-center gap-1.5 text-xs font-medium text-slate-700">
                <t.icon className="h-3 w-3" />{t.label}
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
        <h2 className="font-semibold text-slate-800 mb-0.5">Accent color</h2>
        <p className="text-sm text-slate-500 mb-4">Pick your primary accent color.</p>
        <div className="flex gap-3">
          {ACCENTS.map(a => (
            <button key={a.id} onClick={() => setAccent(a.id)} aria-label={a.id}
              className={`w-8 h-8 rounded-full ${a.cls} transition-all ${
                accent === a.id ? 'ring-2 ring-offset-2 ring-slate-400 scale-110' : 'opacity-70 hover:opacity-100 hover:scale-105'
              }`}
            />
          ))}
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
        <h2 className="font-semibold text-slate-800 mb-0.5">UI density</h2>
        <p className="text-sm text-slate-500 mb-4">Control spacing and padding throughout the app.</p>
        <div className="flex gap-2">
          {['compact', 'comfortable', 'spacious'].map(d => (
            <button key={d} onClick={() => setDensity(d)}
              className={`px-4 py-2 rounded-lg text-sm font-medium capitalize transition-all border ${
                density === d ? 'bg-violet-600 text-white border-violet-600' : 'border-slate-200 text-slate-600 hover:border-slate-300'
              }`}
            >{d}</button>
          ))}
        </div>
      </div>
    </div>
  );
}

