import { useState } from 'react';

const CHANNELS = [
  { id: 'email',    label: 'Email notifications',   desc: 'Receive updates and digests via email.' },
  { id: 'browser',  label: 'Browser notifications',  desc: 'Show desktop push notifications.' },
  { id: 'slack',    label: 'Slack integration',      desc: 'Post activity to a Slack channel.' },
];

const EVENTS = [
  { id: 'comments',  label: 'New comments',          desc: 'When someone comments on your work.' },
  { id: 'mentions',  label: 'Mentions',              desc: 'When you are @mentioned.' },
  { id: 'updates',   label: 'Project updates',       desc: 'Major changes to shared projects.' },
  { id: 'digest',    label: 'Weekly digest',         desc: 'A summary of activity every Monday.' },
];

function Toggle({ enabled, onToggle }: { enabled: boolean; onToggle: () => void }) {
  return (
    <button
      onClick={onToggle}
      className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
        enabled ? 'bg-violet-600' : 'bg-slate-200'
      }`}
      aria-checked={enabled}
      role="switch"
    >
      <span className={`inline-block h-3.5 w-3.5 rounded-full bg-white shadow-sm transition-transform ${
        enabled ? 'translate-x-4' : 'translate-x-0.5'
      }`} />
    </button>
  );
}

export function NotificationSettings() {
  const [channels, setChannels] = useState<Record<string, boolean>>({ email: true, browser: false, slack: false });
  const [events, setEvents] = useState<Record<string, boolean>>({ comments: true, mentions: true, updates: true, digest: false });

  const toggleChannel = (id: string) => setChannels(p => ({ ...p, [id]: !p[id] }));
  const toggleEvent   = (id: string) => setEvents(p => ({ ...p, [id]: !p[id] }));

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
        <h2 className="font-semibold text-slate-800 mb-0.5">Channels</h2>
        <p className="text-sm text-slate-500 mb-5">Where you receive notifications.</p>
        <ul className="divide-y divide-slate-50">
          {CHANNELS.map(c => (
            <li key={c.id} className="flex items-center justify-between py-3.5">
              <div>
                <p className="text-sm font-medium text-slate-800">{c.label}</p>
                <p className="text-xs text-slate-500">{c.desc}</p>
              </div>
              <Toggle enabled={!!channels[c.id]} onToggle={() => toggleChannel(c.id)} />
            </li>
          ))}
        </ul>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6">
        <h2 className="font-semibold text-slate-800 mb-0.5">Event types</h2>
        <p className="text-sm text-slate-500 mb-5">Choose which events trigger a notification.</p>
        <ul className="divide-y divide-slate-50">
          {EVENTS.map(e => (
            <li key={e.id} className="flex items-center justify-between py-3.5">
              <div>
                <p className="text-sm font-medium text-slate-800">{e.label}</p>
                <p className="text-xs text-slate-500">{e.desc}</p>
              </div>
              <Toggle enabled={!!events[e.id]} onToggle={() => toggleEvent(e.id)} />
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
